constexpr int factorial(int n) {
    return (n <= 1) ? 1 : (n * factorial(n - 1));
}

int main() {
    // Computed 100% at compile-time by the compiler
    constexpr int fact5 = factorial(5);
    std::cout << "Compile-Time 5! = " << fact5 << std::endl;
